-- GATE PACK 0271 functions (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select p.proname as obj, pg_catalog.oidvectortypes(p.proargtypes) as args, p.prosecdef as definer,
  coalesce((select substr(c, 13) from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%'), '') as search_path,
  coalesce((select string_agg(r, ',' order by r) from (values ('anon'), ('authenticated'), ('service_role')) as x(r)
            where has_function_privilege(x.r, p.oid, 'EXECUTE')), '') as exec_roles,
  exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE') as exec_public
from pg_catalog.pg_proc p
where p.oid in (pg_catalog.to_regprocedure('public.emit_schedule_signal()'), pg_catalog.to_regprocedure('public.schedule_signal_send(uuid)'))
order by 1, 2;
